// BenchmarkDirectivesContract measures the performance characteristics of any
// implementation of [interfaces.Directives] produced by `factory`. Each
// per-method helper constructs a fresh impl via `factory()` so
// per-benchmark state isolation is the caller's responsibility.
//
// Variadic `opts` carry consumer-supplied extensions:
//   - DirectivesBenchPrePopulate    — one-shot seeder per freshly factory'd impl
//   - DirectivesBenchCustom         — free-form sub-benchmarks
//   - DirectivesBenchOn<Method>     — typed plug-in bench primitives
func BenchmarkDirectivesContract(b *testing.B, factory func() interfaces.Directives, opts ...DirectivesBenchOption) {
	b.Helper()
	cfg := newDirectivesBenchConfig(opts...)

	benchDirectivesLegacy(b, factory, &cfg)

	benchDirectivesOpen(b, factory, &cfg)

	benchDirectivesRead(b, factory, &cfg)

	benchDirectivesRetry(b, factory, &cfg)

	benchDirectivesShard(b, factory, &cfg)

	benchDirectivesShardByKey(b, factory, &cfg)

	benchDirectivesSubmit(b, factory, &cfg)

	benchDirectivesWrap(b, factory, &cfg)

	for _, custom := range cfg.custom {
		b.Run(custom.name, func(b *testing.B) {
			custom.fn(b, factory())
		})
	}
}

// DirectivesBenchOption configures [BenchmarkDirectivesContract].
type DirectivesBenchOption func(*directivesBenchConfig)

// DirectivesBenchPrePopulate runs once against every freshly-factory'd
// impl before per-method benchmarks observe it. Use it for cache
// warm-ups, fixture loading, or any setup the contract treats as
// out-of-band of the per-method primitives.
func DirectivesBenchPrePopulate(fn func(ctx context.Context, impl interfaces.Directives)) DirectivesBenchOption {
	return func(c *directivesBenchConfig) { c.prePopulate = fn }
}

// DirectivesBenchCustom adds a free-form sub-benchmark for measurements
// outside the shape vocabulary — multi-method scenarios, end-to-end
// flows, scenarios where the shape primitives are too granular.
func DirectivesBenchCustom(name string, fn func(*testing.B, interfaces.Directives)) DirectivesBenchOption {
	return func(c *directivesBenchConfig) {
		c.custom = append(c.custom, directivesBenchCustomSub{name: name, fn: fn})
	}
}

// DirectivesBenchSetBytes records bytes processed per iteration
// for a Stream / BatchReader / StreamConsumer method. When set, the
// matching primitive calls b.SetBytes(n) so `go test -bench` reports
// MB/s alongside ns/op. Methods of other shapes ignore the value.
func DirectivesBenchSetBytes(method string, n int64) DirectivesBenchOption {
	return func(c *directivesBenchConfig) {
		if c.bytesPerOp == nil {
			c.bytesPerOp = map[string]int64{}
		}
		c.bytesPerOp[method] = n
	}
}

